using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Attendance;
using PeopleHub.Application.Modules.Leave;
using PeopleHub.Application.Modules.Organization;
using PeopleHub.Application.Modules.Requests;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class HolidayCalendarTests
{
 class User(bool allowed=true):ICurrentUser{public string Email=>"holiday@example.local";public int? EmployeeId=>6;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>allowed;public bool Can(string p)=>allowed;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static HolidayService S(AppDbContext d,bool allowed=true){var u=new User(allowed);var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c));}
 [Fact]public void GlobalBranchDepartmentIntersectionAndHistoricalAssignmentAreApplied(){var e=new Employee{Id=6,BranchId=1,DepartmentId=2};var day=new DateTime(2026,12,1);Assert.True(HolidayCalendar.Applies(new(),e,day,[]));Assert.False(HolidayCalendar.Applies(new(){BranchId=2},e,day,[]));Assert.True(HolidayCalendar.Applies(new(){BranchId=1,DepartmentId=2},e,day,[]));Assert.False(HolidayCalendar.Applies(new(){BranchId=1,DepartmentId=3},e,day,[]));var history=new[]{new EmployeeAssignment{EmployeeId=6,BranchId=2,DepartmentId=3,EffectiveFrom=day.AddDays(-1),EffectiveTo=day.AddDays(1)}};Assert.True(HolidayCalendar.Applies(new(){BranchId=2,DepartmentId=3},e,day,history));Assert.False(HolidayCalendar.Applies(new(){BranchId=2,DepartmentId=3},e,day.AddDays(1),history));}
 [Fact]public async Task HolidaysRequirePermissionFutureDateReasonAndValidScope(){await using var d=await Db();var c=new AppClock(TimeProvider.System);await Assert.ThrowsAsync<DomainException>(()=>S(d,false).AddAsync(c.Today.AddDays(1),"Demo",null,null,null,"Test"));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddAsync(c.Today,"Demo",null,null,null,"Test"));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddAsync(c.Today.AddDays(1),"Demo",null,999,null,"Test"));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddAsync(c.Today.AddDays(1),"Demo",null,null,null,""));await S(d).AddAsync(c.Today.AddDays(1),"Demo scoped holiday",null,1,null,"Fictional policy");await Assert.ThrowsAsync<DomainException>(()=>S(d).AddAsync(c.Today.AddDays(1),"Duplicate",null,1,null,"Test"));Assert.Single(await d.Set<Holiday>().Where(x=>x.Name=="Demo scoped holiday").ToListAsync());}
 [Fact]public async Task AttendanceCalendarUsesOnlyEmployeeScope(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;var day=new DateTime(2026,12,1);d.Add(new Holiday{Date=day,Name="Different branch",BranchId=999});d.Add(new Holiday{Date=day.AddDays(1),Name="Own branch",BranchId=e.BranchId});await d.SaveAsync();var u=new User();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var s=new AttendanceService(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a));var rows=await s.MonthAsync(6,2026,12);Assert.True(rows.Single(x=>x.Date==day).IsWorkingDay);Assert.False(rows.Single(x=>x.Date==day.AddDays(1)).IsWorkingDay);Assert.Equal("Own branch",rows.Single(x=>x.Date==day.AddDays(1)).HolidayName);}
 [Fact]public async Task LeaveDurationAndSummaryUseEmployeeHolidayScope(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;var day=new DateTime(2026,12,1);d.Add(new Holiday{Date=day,Name="Other branch",BranchId=999});d.Add(new Holiday{Date=day.AddDays(1),Name="Own branch",BranchId=e.BranchId});await d.SaveAsync();var u=new User();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var n=new NotificationService(d,u,c);var f=new WorkflowService(d,u,a);d.Set<LeaveRequest>().RemoveRange(await d.Set<LeaveRequest>().Where(x=>x.EmployeeId==6).ToListAsync());await d.SaveAsync();var leave=new LeaveService(d,new AccessScope(d,u),u,a,n,c,f);var type=await d.Set<LeaveType>().FirstAsync(x=>x.IsPaid&&x.DeductsBalance);await leave.RequestAsync(type.Id,day,day.AddDays(1),"Holiday test",null);var request=await d.Set<LeaveRequest>().SingleAsync(x=>x.EmployeeId==6&&x.StartDate==day);Assert.Equal(1,request.Days);var att=new AttendanceService(d,new AccessScope(d,u),u,a,n,c,f);var summary=(await att.SummariesAsync([e],2026,12))[6];var expected=AttendanceCalculator.CountWorkingDays(day,new DateTime(2026,12,31),[day.AddDays(1)]);Assert.Equal(expected,summary.WorkingDays);}
}
